@using sv_7b1e262e5c1d4e1fa82971c31d5f0cd8.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label text-white mb-1" for="warehouseSelect">Current Warehouse</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelectionChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelectionChanged(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_7b1e262e5c1d4e1fa82971c31d5f0cd8.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        0 => "bg-success",
