toolArgs.file_text:
@page "/dashboard"
@using sv_7b1e262e5c1d4e1fa82971c31d5f0cd8.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@CurrentWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text">
                    <span class="fs-1 @AlertTextClass">@AlertService.CurrentLowStockCount</span>
                    <br />
                    <small class="text-muted">items below minimum level</small>
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text fs-4 text-success">● Active</p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private string CurrentWarehouseName =>
        WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
        ?? WarehouseState.CurrentWarehouseId;

    private string AlertTextClass => AlertService.CurrentLowStockCount switch
    {
        0 => "text-success",
        <= 5 => "text-warning",
        _ => "text-danger"
    };

    protected override void OnInitialized()
    {
        AlertService.Subscribe();
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.Unsubscribe();
    }
}

